package pagos;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.net.URI;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import config.ConfiguracionMercadoPago;
class MercadoPagoPasarelaTest {private ConfiguracionMercadoPago config(){return ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","TEST-token","MP_WEBHOOK_SECRET","firma","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123"));}private SolicitudCheckout solicitud(){return new SolicitudCheckout(4,9,new BigDecimal("6250.00"),"ARS","Seña Cancha 2","reserva:9",LocalDateTime.of(2026,10,14,11,0),URI.create("https://club.example/ok"),URI.create("https://club.example/pendiente"),URI.create("https://club.example/error"),URI.create("https://club.example/webhook"),"idem-4");}@Test void creaPreferenciaConIdempotenciaYRetornos(){List<String> capturada=new ArrayList<>();MercadoPagoHttpTransport t=(m,u,h,b)->{capturada.add(m);capturada.add(u.toString());capturada.add(h.get("X-Idempotency-Key"));capturada.add(b);return new MercadoPagoHttpTransport.Respuesta(201,"{\"id\":\"pref-1\",\"init_point\":\"https://www.mercadopago.com/checkout/v1/redirect\"}");};var p=new MercadoPagoPasarela(config(),t,new ObjectMapper().findAndRegisterModules());var c=p.crearCheckout(solicitud());assertEquals("pref-1",c.preferenciaId());assertEquals("idem-4",capturada.get(2));assertTrue(capturada.get(3).contains("external_reference"));assertTrue(capturada.get(3).contains("notification_url"));assertFalse(capturada.get(3).contains("TEST-token"));}@Test void consultaPagoSinExponerTokenEnUrl(){List<String> capturada=new ArrayList<>();MercadoPagoHttpTransport t=(m,u,h,b)->{capturada.add(u.toString());assertTrue(h.get("Authorization").startsWith("Bearer "));return new MercadoPagoHttpTransport.Respuesta(200,"{\"id\":123,\"external_reference\":\"reserva:9\",\"status\":\"approved\",\"status_detail\":\"accredited\",\"transaction_amount\":6250,\"currency_id\":\"ARS\",\"date_approved\":\"2026-10-14T10:00:00-03:00\"}");};var pago=new MercadoPagoPasarela(config(),t,new ObjectMapper().findAndRegisterModules()).consultarPago("123");assertTrue(pago.aprobado());assertEquals(new BigDecimal("6250"),pago.importe());assertFalse(capturada.getFirst().contains("TEST-token"));}@Test void errorHttpSeTraduceSinCuerpoSensible(){MercadoPagoHttpTransport t=(m,u,h,b)->new MercadoPagoHttpTransport.Respuesta(401,"{\"message\":\"Unauthorized\"}");var p=new MercadoPagoPasarela(config(),t,new ObjectMapper());var ex=assertThrows(IllegalStateException.class,()->p.crearCheckout(solicitud()));assertTrue(ex.getMessage().contains("HTTP 401"));assertFalse(ex.getMessage().contains("TEST-token"));}}
